from abc import ABCMeta, abstractmethod
import logging
import os
import six
from taf.internal.core import NamedGroup, NamedObject
from taf.internal.execution.local import LocalExecutor

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CollectableGroupBase(object):
    """
    Base class for collectable groups (sync and async).
    """
    def _clear_has_collected(self):
        """
        Clear the "_has_collected" attribute for all members.
        """
        for member in self._members:
            member._clear_has_collected()


@six.add_metaclass(ABCMeta)
class CollectableObjectBase(object):
    def __init__(self, **kwargs):
        super(CollectableObjectBase, self).__init__(**kwargs)
        self._has_collected = False

    def _clear_has_collected(self):
        self._has_collected = False


@six.add_metaclass(ABCMeta)
class CollectableComponentBase(object):

    def __init__(self, local_executor=None, **kwargs):
        super(CollectableComponentBase, self).__init__(**kwargs)
        self._local_executor = local_executor if local_executor is not None else LocalExecutor()

    def _create_dir(self, path):
        """
        Create a directory in the local filesystem.

        :param str path: path of directory that shall be created
        """
        self._local_executor.execute(f"mkdir -p '{path}'".encode())

    @abstractmethod
    def _clear_has_collected(self):
        """
        Clear the "_has_collected" attribute.
        """

@six.add_metaclass(ABCMeta)
class CollectableComponent(CollectableComponentBase):
    """
    An object, that can collect information from source locations.

    A collectable component can either be a single collectable object
    or a group of collectable components.

    Examples for source locations are files in the filesystem of a remote host, local files in another
    directory than the target_dir or information retrievable via HTTP.
    """

    def collect(self, target_dir, _first=True):
        """
        Collect information from source locations.

        Each collector component creates an own subdirectory below target_dir.

        If this object has collected the information already during the same user-initiated collect() call,
        don't collect the information again.

        :param str target_dir:
            Target directory, where collected information shall be stored on the local host,
            Multiple user-initiated calls of collect() on the same collectable component must use different values
            for target_dir to avoid overwriting previously collected files.
        :param boolean _first:
            internal flag to distinguish the user-initiated collect() call from resulting internal collect() calls
        """
        target_dir = os.path.join(target_dir, self._name)
        self._create_dir(path=target_dir)
        self._do_collect(target_dir=target_dir)
        if _first:
            self._clear_has_collected()

    @abstractmethod
    def _do_collect(self, target_dir):
        """
        Collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """


@six.add_metaclass(ABCMeta)
class CollectableObject(CollectableObjectBase, NamedObject, CollectableComponent):
    """
    Collectable object.
    """

    def _do_collect(self, target_dir):
        """
        Collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """
        if not self._has_collected:
            self._collect(target_dir=target_dir)
            self._has_collected = True

    @abstractmethod
    def _collect(self, target_dir):
        """
        Collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """


class CollectableGroup(CollectableGroupBase, NamedGroup, CollectableComponent):
    """
    Group of collectable components.
    """

    def _do_collect(self, target_dir):
        """
        Collect information from source locations.

        :param target_dir:
            target directory, where collected information shall be stored on the local host
        """
        for member in self._members:
            member.collect(target_dir=target_dir, _first=False)
